import random
import time

class Player:
    def __init__(self, name):
        self.name = name
        self.health = 100
        self.score = 0

    def take_damage(self, amount):
        self.health -= amount
        if self.health < 0:
            self.health = 0

    def is_alive(self):
        return self.health > 0

    def gain_score(self, points):
        self.score += points

class Enemy:
    def __init__(self, name, health):
        self.name = name
        self.health = health

    def take_damage(self, amount):
        self.health -= amount
        if self.health < 0:
            self.health = 0

    def is_alive(self):
        return self.health > 0

def display_status(player, enemy):
    print(f"\n{player.name} - Health: {player.health} | Score: {player.score}")
    print(f"{enemy.name} - Health: {enemy.health}\n")

def play_round(player, enemy):
    print(f"{player.name} attacks {enemy.name}!")
